import{c as a,S as e,j as l,m as i}from"./chunks/framework.8aa1YH_s.js";const d=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 15: Kelime Türleri - Zarflar (Belirteçler)","description":"","frontmatter":{},"headers":[],"relativePath":"15 Kelime Türleri - Zarflar (Belirteçler).md","filePath":"15 Kelime Türleri - Zarflar (Belirteçler).md"}'),n={name:"15 Kelime Türleri - Zarflar (Belirteçler).md"};function t(s,r,o,m,k,u){return e(),l("div",null,[...r[0]||(r[0]=[i('<h1 id="turk-dil-bilgisi-serisi-15-kelime-turleri-zarflar-belirtecler" tabindex="-1">Türk Dil Bilgisi Serisi - 15: Kelime Türleri - Zarflar (Belirteçler) <a class="header-anchor" href="#turk-dil-bilgisi-serisi-15-kelime-turleri-zarflar-belirtecler" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 15: Kelime Türleri - Zarflar (Belirteçler)”">​</a></h1><p>Kelime türleri yolculuğumuzda isimleri, sıfatları ve zamirleri tamamladık. Bu yazımızda, dildeki hareketlerin ve eylemlerin nasıl, ne zaman, ne kadar ve nerede yapıldığını gösteren, yani fiillerin adeta kılavuzu olan <strong>Zarflar (Belirteçler)</strong> konusunu ele alıyoruz.</p><p>Prof. Dr. Muharrem Ergin’e göre zarflar, tıpkı sıfatlar gibi tek başlarına bağımsız birer nesneyi temsil etmezler. Bir sıfatın var olması için nasıl bir isme ihtiyaç varsa, bir zarfın var olması için de çoğunlukla bir <strong>fiile, fiilimsiye, sıfata</strong> veya <strong>kendi türünden başka bir zarfa</strong> ihtiyaç vardır.</p><p>Muharrem Ergin sistematiğinde zarflar, yüklendikleri anlam ve işlevlerine göre <strong>5 ana gruba</strong> ayrılır:</p><hr><h2 id="_1-tarz-durum-nitelik-zarfları" tabindex="-1">1. Tarz (Durum / Nitelik) Zarfları <a class="header-anchor" href="#_1-tarz-durum-nitelik-zarfları" aria-label="Permalink to “1. Tarz (Durum / Nitelik) Zarfları”">​</a></h2><p>Eylemin, hareketin <strong>nasıl</strong> yapıldığını, ne şekilde meydana geldiğini bildiren zarflardır. Fiile veya fiilimsiye sorulan <strong>&quot;Nasıl?&quot;</strong> sorusunun cevabıdırlar.</p><ul><li><em>Örnekler:</em><ul><li>Çocuk <strong>yavaşça</strong> yerinden kalktı. (<em>Nasıl kalktı? -&gt; Yavaşça</em>)</li><li>Soruları <strong>gülerek</strong> cevapladı. (<em>Nasıl cevapladı? -&gt; Gülerek</em>)</li><li>Bu projeyi <strong>güzel</strong> hazırlamışsın. (<em>Nasıl hazırlamışsın? -&gt; Güzel</em>)</li></ul></li></ul><blockquote><p><strong>⚠️ Sıfatla Karıştırma Akıllı İpucu:</strong> Aynı kelime bir ismin önündeyse <strong>sıfat</strong>, bir fiilin önündeyse <strong>zarftır</strong>.</p><ul><li><strong>Güzel</strong> araba (İsmin önünde -&gt; Sıfat)</li><li><strong>Güzel</strong> konuştu (Fiilin önünde -&gt; Zarf)</li></ul></blockquote><hr><h2 id="_2-zaman-zarfları" tabindex="-1">2. Zaman Zarfları <a class="header-anchor" href="#_2-zaman-zarfları" aria-label="Permalink to “2. Zaman Zarfları”">​</a></h2><p>Eylemin, hareketin veya oluşun <strong>ne zaman</strong> gerçekleştiğini veya gerçekleşeceğini bildiren zarflardır. Fiile sorulan <strong>&quot;Ne zaman?&quot;</strong> sorusunun cevabıdırlar.</p><ul><li><strong>Dün, bugün, yarın, şimdi, ansızın, sabahleyin, henüz, hâlâ...</strong></li><li><em>Örnekler:</em><ul><li>Toplantı <strong>yarın</strong> başlayacak. (<em>Ne zaman başlayacak? -&gt; Yarın</em>)</li><li>Aradığın evrakları <strong>şimdi</strong> sisteme yükledim. (<em>Ne zaman yükledim? -&gt; Şimdi</em>)</li><li><strong>Sabahleyin</strong> yola çıkacağız. (<em>Ne zaman çıkacağız? -&gt; Sabahleyin</em>)</li></ul></li></ul><hr><h2 id="_3-miktar-azlık-cokluk-derecelendirme-zarfları" tabindex="-1">3. Miktar (Azlık-Çokluk / Derecelendirme) Zarfları <a class="header-anchor" href="#_3-miktar-azlık-cokluk-derecelendirme-zarfları" aria-label="Permalink to “3. Miktar (Azlık-Çokluk / Derecelendirme) Zarfları”">​</a></h2><p>Bir fiilin, bir sıfatın veya başka bir zarfın ölçüsünü, miktarını, derecesini bildiren zarflardır. Söz konusu unsurun önüne gelerek onun etkisini artırır veya azaltırlar. Sorusu **&quot;Ne kadar?&quot;**dır.</p><ul><li><strong>En, daha, pek, çok, az, biraz, oldukça, fazla...</strong></li><li><em>Örnekler:</em><ul><li>Bu hafta <strong>çok</strong> çalıştık. (<em>Ne kadar çalıştık? -&gt; Çok [Fiili miktar yönünden etkilemiş]</em>)</li><li>O, <strong>en</strong> başarılı yazılımcıdır. (<em>Ne kadar başarılı? -&gt; En [Sıfatı derece yönünden etkilemiş]</em>)</li><li><strong>Daha</strong> hızlı koşmalısın. (<em>Ne kadar hızlı? -&gt; Daha [Başka bir zarfı derece yönünden etkilemiş]</em>)</li></ul></li></ul><hr><h2 id="_4-yer-yon-zarfları" tabindex="-1">4. Yer-Yön Zarfları <a class="header-anchor" href="#_4-yer-yon-zarfları" aria-label="Permalink to “4. Yer-Yön Zarfları”">​</a></h2><p>Fiillerin veya fiilimsilerin yöneldiği, yön tuttuğu coğrafi veya mekânsal doğrultuyu bildiren zarflardır. Türkçede yer-yön zarfı olarak kullanılan kelime kadrosu oldukça sınırlıdır: <strong>Aşağı, yukarı, içeri, dışarı, ileri, geri, beri, öte.</strong></p><ul><li><em>Örnekler:</em><ul><li>Biraz <strong>ileri</strong> git.</li><li>Lütfen <strong>içeri</strong> giriniz.</li><li>Çocuk <strong>yukarı</strong> çıktı.</li></ul></li></ul><blockquote><p><strong>🚨 Muharrem Ergin&#39;in Altın Değerinde Uyarısı:</strong> Yer-yön bildiren kelimelerin &quot;zarf&quot; sayılabilmesi için <strong>asla ve asla isim çekim eki (hal ekleri) almamaları, yani eksiz olmaları gerekir</strong>. Eğer bu kelimeler ek alırlarsa anında <strong>isimleşirler</strong>.</p><ul><li>İçeri gir. (Eksiz -&gt; <strong>Yer-Yön Zarfı</strong>)</li><li>İçeri<strong>ye</strong> gir. (Yönelme hal eki almış -&gt; <strong>İsim</strong>)</li><li>Yukarı bak. (Eksiz -&gt; <strong>Yer-Yön Zarfı</strong>)</li><li>Yukarı<strong>dan</strong> ses geldi. (Ayrılma hal eki almış -&gt; <strong>İsim</strong>)</li></ul></blockquote><hr><h2 id="_5-soru-zarfları" tabindex="-1">5. Soru Zarfları <a class="header-anchor" href="#_5-soru-zarfları" aria-label="Permalink to “5. Soru Zarfları”">​</a></h2><p>Fiillerin veya fiilimsilerin anlamını zaman, tarz, sebep veya miktar yönünden soru yoluyla araştıran kelimelerdir. Cevapları da yine bir zarftır.</p><ul><li><strong>Nasıl, ne zaman, ne kadar, niçin, neden, niye...</strong></li><li><em>Örnekler:</em><ul><li>İstanbul&#39;a <strong>ne zaman</strong> geleceksin? (<em>Yarın -&gt; Zaman Zarfı</em>)</li><li>Bu hatayı <strong>nasıl</strong> düzelttin? (<em>Kodları inceleyerek -&gt; Tarz Zarfı</em>)</li><li>Beni <strong>niçin</strong> aramadın? (<em>İşim olduğu için -&gt; Sebep bildiren soru zarfı</em>)</li></ul></li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Prof. Dr. Muharrem Ergin&#39;in sistematiğinde zarflar, dildeki eylemlerin sınır çizgilerini çizen mimarlardır. Fiillerin kuru birer hareket olarak kalmasını engeller; onlara zamanın ruhunu, mekanın yönünü, miktarın derecesini ve tarzın estetiğini katarlar. Bir kelimenin zarf olup olmadığını anlamanın yegane yolu, onun bir fiille, sıfatla veya başka bir zarfla kurduğu o dinamik bağa bakmaktır.</p>',29)])])}const f=a(n,[["render",t]]);export{d as __pageData,f as default};
